--
-- Name: unit_tree_view; Type: VIEW; Schema: public; Owner: taiping_user
--

CREATE VIEW public.unit_tree_view AS
 WITH RECURSIVE unit_tree AS (
         SELECT unit_hierarchy.id,
            unit_hierarchy.unit_level,
            unit_hierarchy.unit_name,
            unit_hierarchy.parent_id,
            unit_hierarchy.school_dict_id,
            unit_hierarchy.full_path,
            1 AS depth,
            ARRAY[unit_hierarchy.id] AS path_ids,
            ARRAY[(unit_hierarchy.unit_name)::character varying] AS path_names
           FROM public.unit_hierarchy
          WHERE (unit_hierarchy.parent_id IS NULL)
        UNION ALL
         SELECT u.id,
            u.unit_level,
            u.unit_name,
            u.parent_id,
            u.school_dict_id,
            u.full_path,
            (ut.depth + 1),
            (ut.path_ids || u.id) AS int4,
            (ut.path_names || u.unit_name) AS "varchar"
           FROM (public.unit_hierarchy u
             JOIN unit_tree ut ON ((u.parent_id = ut.id)))
        )
 SELECT id,
    unit_level,
    unit_name,
    parent_id,
    school_dict_id,
    full_path,
    depth,
    path_ids,
    path_names
   FROM unit_tree;


ALTER VIEW public.unit_tree_view OWNER TO taiping_user;

