--
-- Name: v_checklist_statistics; Type: VIEW; Schema: public; Owner: taiping_user
--

CREATE VIEW public.v_checklist_statistics AS
 SELECT "模板id",
    count(*) AS "总实例数",
    sum(
        CASE
            WHEN (("状态")::text = '待处理'::text) THEN 1
            ELSE 0
        END) AS "待处理数",
    sum(
        CASE
            WHEN (("状态")::text = '进行中'::text) THEN 1
            ELSE 0
        END) AS "进行中数",
    sum(
        CASE
            WHEN (("状态")::text = '已完成'::text) THEN 1
            ELSE 0
        END) AS "已完成数",
    sum(
        CASE
            WHEN (("状态")::text = '已逾期'::text) THEN 1
            ELSE 0
        END) AS "已逾期数",
    avg("完成进度") AS "平均进度",
    max("创建时间") AS "最新创建时间"
   FROM public.business_checklist_instances
  GROUP BY "模板id";


ALTER VIEW public.v_checklist_statistics OWNER TO taiping_user;

